/bin/zsh -lc "node <<'NODE'
const fs = require('node:fs');
const cp = require('node:child_process');
const root = process.cwd();
const sha = cp.execFileSync('git', ['rev-parse', 'HEAD'], {cwd: root, encoding: 'utf8'}).trim();
fs.readFileSync('change.diff', 'utf8');
const reason = 'Isolated reviewer spawning is unavailable in this evaluation runtime.';
const reviewer = (agentType, specPath) => ({agent_type: agentType, spec_path: specPath, status: 'not_started', reason, model: 'gpt-5.6-sol', reasoning_effort: 'medium', agent_id: null, context_id: null, findings: null, verdict: null});
const result = {
  workspace_root: root,
  fixed_point: {ref: 'HEAD', commit: sha},
  diff_source: 'change.diff',
  status: 'blocked',
  isolated_subagents_available: false,
  reviewers: {
    Standards: reviewer('standards_reviewer', 'docs/specs/496/product-spec.md'),
    Spec: reviewer('spec_reviewer', 'docs/specs/496/architecture-spec.md')
  },
  review_verdict_available: false,
  verdict: null,
  unresolved_blockers: [reason],
  inline_review_performed: false
};
const target = '.eval-output/review/contexts.json';
fs.mkdirSync('.eval-output/review', {recursive: true});
fs.writeFileSync(target, JSON.stringify(result, null, 2) + '\\n');
if ("'!fs.existsSync(target)) throw new Error('"'Output file is missing');
const parsed = JSON.parse(fs.readFileSync(target, 'utf8'));
if (parsed.review_verdict_available "'!== false || Object.values(parsed.reviewers).some(r => r.status !== '"'not_started' || r.agent_id "'!== null || r.context_id !== null || r.verdict !== null)) throw new Error('"'Unexpected review state');
console.log('Verified: ' + target + ' exists, parses as JSON, and records both reviewers as not started with no verdict.');
NODE"

